 for(row in .cr_de_sorted(rows,'case_id')){
 base<-baseline[[row$case_id]];if(row$decision_date!=base$decision_date||row$weight!=base$weight) .cr_error('DECISION_ROBUSTNESS_CONTRACT','Shared scenarios preserve case dates and weights');decision<-parse_case(row);action<-decision$action;baseline_action<-decisions[[row$case_id]]$action;w<-row$weight;changed_sources<-Filter(function(k).cr_hash(row[[k]])!=.cr_hash(base[[k]]),c('risk','affordability','eligibility','operations'));flip<-action!=baseline_action;flips<-c(flips,w*flip);both_approved<-action=='APPROVE'&&baseline_action=='APPROVE';amount_change<-if(both_approved)row$offer_terms$amount-base$offer_terms$amount else NULL;price_change<-if(both_approved)row$offer_terms$annual_rate-base$offer_terms$annual_rate else NULL;terms_changed<-both_approved&&(abs(amount_change)>tolerance||abs(price_change)>tolerance);term_changes<-c(term_changes,w*terms_changed);feasible<-row$feasible_by_action[[action]];violations<-c(violations,w*identical(feasible,FALSE));if(is.null(feasible)&&sw*w>0)unidentified<-union(unidentified,'selected_action_feasibility')
 utilities<-row$utility_by_action;all_known<-all(vapply(.cr_dv_actions,function(a)!is.null(row$feasible_by_action[[a]])&&(!row$feasible_by_action[[a]]||!is.null(utilities[[a]])),TRUE));available<-unlist(lapply(.cr_dv_actions,function(a)if(identical(row$feasible_by_action[[a]],TRUE)&&!is.null(utilities[[a]]))utilities[[a]]else NULL),use.names=FALSE);regret<-if(all_known&&length(available)&&identical(feasible,TRUE)&&!is.null(utilities[[action]]))max(0,.cr_de_sum(c(max(available),-utilities[[action]])))else NULL
 if(is.null(regret)&&w>0)regret_known<-FALSE else values<-c(values,w*if(is.null(regret))0 else regret)
 case_results[[length(case_results)+1L]]<-list(case_id=row$case_id,baseline_action=baseline_action,action=action,action_flipped=flip,changed_input_sources=as.list(changed_sources),amount_change_if_both_approved=amount_change,annual_rate_change_if_both_approved=price_change,terms_changed_if_both_approved=terms_changed,selected_action_feasible=feasible,scenario_regret=regret,decision=decision)
 }
 scenario_regret<-if(regret_known).cr_de_sum(values)/total else NULL;if(!is.null(scenario_regret)&&sw>0)regrets<-c(regrets,scenario_regret)else if(sw>0)unidentified<-union(unidentified,'utility_regret');flip_rate<-.cr_de_sum(flips)/total;term_rate<-.cr_de_sum(term_changes)/total;violation_rate<-.cr_de_sum(violations)/total;weighted_flips<-c(weighted_flips,sw*flip_rate);weighted_terms<-c(weighted_terms,sw*term_rate);weighted_violations<-c(weighted_violations,sw*violation_rate);paths[[length(paths)+1L]]<-list(scenario_id=scenario$scenario_id,scenario_weight=sw,action_flip_rate=flip_rate,offer_term_change_rate_on_all_cases=term_rate,known_infeasible_action_rate=violation_rate,mean_scenario_regret=scenario_regret,cases=case_results)
 }
 if(!length(scenarios)||abs(.cr_de_sum(weights)-1)>1e-12) .cr_error('DECISION_ROBUSTNESS_CONTRACT','Normalized nonnegative finite scenario weights required')
 value<-.cr_de_bound(list(schema_version='1.0',kind='PolicyRobustness',policy_hash=policy$sha256,profile=profile,as_of=as_of,baseline_hash=.cr_hash(baseline_cases),perturbation_hash=.cr_hash(perturbation_scenarios),weighted_action_flip_rate=.cr_de_sum(weighted_flips),weighted_offer_term_change_rate=.cr_de_sum(weighted_terms),weighted_known_infeasible_action_rate=.cr_de_sum(weighted_violations),worst_case_mean_regret=if('utility_regret'%in%unidentified||!length(regrets))NULL else max(regrets),unidentified_dimensions=as.list(sort(unidentified)),scenarios=paths))
 .cr_result(value,'decisioning.assess_policy_robustness','policy_robustness',ctx,diagnostics=.cr_empty_object(),limitations='Finite supplied shared perturbations, not a worst-case guarantee outside this set or an automatically valid confidence interval. Bootstrap validity, dependence and generation design are caller responsibilities. Changed input sources record association with flips, not causal attribution. Amount/rate changes are supplied offer scenarios; the fixed rule policy itself does not price or optimize limits. Regret compares only explicitly feasible actions with fully supplied scenario utilities; unknown utility or feasibility remains unidentified. No policy is refitted or selected on these scenarios.')
